int main(){api::EngineRequestContext c;c.database_path=(std::filesystem::temp_directory_path()/std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())).string();c.database_uuid.canonical="019d0000-0000-7000-8000-000000002399";c.security_context_present=true;c.trace_tags={"right:SBLR_EXECUTOR_AVAILABILITY_ADMIN"};api::SblrExecutorAvailabilityRowIdentity row{api::kSblrReadRangeExecutorId,516,"1.0",api::kSblrReadRangeOperandDescriptorId,api::kSblrReadRangeResultDescriptorId,1};auto initial=api::LoadSblrExecutorAvailabilitySnapshot(c,row);assert(initial.ok&&initial.snapshot.installed);api::SblrExecutorAvailabilitySetRequest request;request.database_uuid=c.database_uuid.canonical;request.expected_snapshot_uuid=initial.snapshot.snapshot_uuid;request.expected_generation=initial.snapshot.generation;request.exact_row_identity=row;request.requested_state=api::SblrExecutorAvailabilityState::revoked;request.reason_code="CSC-TEST-002399";assert(api::SetSblrExecutorAvailability(c,request).ok);api::SblrExecutorAvailabilitySnapshot current;assert(api::RevalidateSblrExecutorAvailability(c,row,initial.snapshot,&current).code=="SBLR.OPCODE.EXECUTOR_EVIDENCE_MISSING");std::error_code ec;std::filesystem::remove(c.database_path+".sb.sblr_executor_availability_registry.v1.read_range",ec);}
